import {majors,dimensions,tasks,goals,strengths,sources} from './majors.js';
import {buildIndex,rankMajors,filterRecords,subjectSelectionValid,checkRequirement,validateHistory,compareRank,csvCell} from './engine.js';
import {createWorkspace} from './workspace.js';
const KEY='hebei-major-compass-v1';
const defaults=()=>({first:'',electives:[],rank:'',budget:'',maxYears:'any',grad:'unsure',health:'unknown',interests:{},strengths:[],goals:[],veto:[],compare:[],saved:[],done:false,step:0});
let p=defaults();
try{const v=JSON.parse(localStorage.getItem(KEY));if(v&&typeof v==='object'){for(const k of ['first','rank','budget','maxYears','grad','health'])if(typeof v[k]==='string')p[k]=v[k];for(const k of ['electives','strengths','goals','veto','compare'])if(Array.isArray(v[k]))p[k]=v[k].filter(x=>typeof x==='string');if(Array.isArray(v.saved))p.saved=v.saved.filter(Number.isInteger).slice(0,96);if(v.interests&&typeof v.interests==='object')for(const [k,val] of Object.entries(v.interests))if(dimensions.some(d=>d[0]===k)&&(val===null||(Number.isInteger(val)&&val>=0&&val<=4)))p.interests[k]=val;p.done=!!v.done;p.step=Number.isInteger(v.step)?Math.max(0,Math.min(3,v.step)):0;}}catch{}
let db,index,view='planner',showAll=false,filters={school:'',major:'',level:'本科',onlyEligible:true},page=0,history=[],busy=false;
const app=document.getElementById('app'),dialog=document.getElementById('detailDialog'),dialogBody=document.getElementById('dialogBody');
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const fmt=n=>Number(n).toLocaleString('zh-CN');
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(p));}catch{toast('当前浏览器无法保存进度，页面关闭前请导出结果。');}};
let toastTimer;function toast(s){const e=document.getElementById('toast');e.textContent=s;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),3200);}
function choose(key,value,label,selected,extra=''){return `<button type="button" class="choice ${extra}" aria-pressed="${selected}" data-choice="${esc(key)}" data-value="${esc(value)}">${esc(label)}</button>`;}
function options(key,items){return `<div class="choices">${items.map(([v,l])=>choose(key,v,l,p[key]===v)).join('')}</div>`;}
function checks(key,items){return `<div class="choices">${Object.entries(items).map(([v,l])=>choose(key,v,l,p[key].includes(v))).join('')}</div>`;}
function field(label,content,hint=''){return `<div class="field"><div class="field-label">${label}</div>${content}${hint?`<p class="hint">${hint}</p>`:''}</div>`;}
function title(k,h,t){return `<div class="intro"><div class="eyebrow">${k}</div><h1>${h}</h1><p>${t}</p></div>`;}
function sidebar(){return `<aside class="sidebar"><div class="side-title">从条件到具体选择</div><div class="steps">${['基本条件','学习兴趣','目标与底线','筛选结果'].map((s,i)=>`<button class="stepnav ${p.step===i?'active':''}" data-step="${i}" ${p.step===i?'aria-current="step"':''}><span class="stepnum">${i+1}</span><span>${s}</span></button>`).join('')}</div><div class="side-note"><strong>河北 · 3＋1＋2</strong>本科批按“专业（类）＋学校”组织候选。<br>依2026年已公布规则，2027年需复核。<br><br><strong>${fmt(db.records.length)} 条官方拟招记录</strong>选科表不等于当年招生计划。兴趣匹配也不代表录取概率。</div></aside>`;}
function stepActions(){return `<div id="validation" class="error-message" role="alert"></div><div class="actions">${p.step?'<button class="btn" data-action="prev">上一步</button>':'<span class="small">可以随时修改，进度自动保存在本机</span>'}<div class="right"><span class="small">${p.step+1} / 3</span><button class="btn primary" data-action="next">${p.step===2?'查看筛选结果':'下一步'} <span aria-hidden="true">→</span></button></div></div>`;}
function profileStep(){return `${title('01 / 基本条件','先确定你的选择范围','不用填写姓名和联系方式。先选科，再设定培养年限与家庭条件。')}<div class="panel">
${field('首选科目 <span class="small">必选一项</span>',options('first',[['物理','物理'],['历史','历史']]))}
${field('再选科目 <span class="small">必选两项</span>',checks('electives',{'化学':'化学','生物':'生物','思想政治':'思想政治','地理':'地理'}),'以河北2027年已公布的具体院校专业科目要求进行匹配。')}
<div class="grid2">${field('<label for="rank">本省同类考生位次（可选）</label>',`<input class="input" id="rank" data-field="rank" inputmode="numeric" type="number" min="1" max="1000000" placeholder="出分后填写，例：35000" value="${esc(p.rank)}">`,'没有位次也能筛专业。院校位次对比须另导入有来源的历史数据。')}
${field('<label for="budget">每年学费预算（可选，元）</label>',`<input class="input" id="budget" data-field="budget" inputmode="numeric" type="number" min="0" max="1000000" placeholder="例如：10000，不含生活费" value="${esc(p.budget)}">`,'官方选科表不含学费；预算会列入候选核查，未核实前不自动判定符合。')}</div>
${field('可以接受的本科学制',options('maxYears',[['4','只考虑不超过4年'],['any','可以考虑5年或更长']]))}
${field('继续深造的意愿',options('grad',[['no','希望本科后直接就业'],['yes','愿意继续读研'],['unsure','还没想清楚']]))}
${field('高考体检结论',options('health',[['unknown','还未取得或未核对'],['clear','已核对，暂无已知受限项'],['review','存在需要逐项核查的限制']]),'系统不根据健康信息代替学校判定可报；结果会提醒逐条核查体检、语种和单科要求。')}
</div>${stepActions()}`;}
function interestsStep(){const known=Object.keys(p.interests).length;return `${title('02 / 学习兴趣','这些学习任务，你愿意做吗？','按愿意投入的程度回答，不用猜专业名称。没体验过可以选“不了解”，它不会被当成中等兴趣。')}<div class="panel"><div class="panel-header"><h3>10个问题，找到投入方向</h3><span class="count-indicator">已回答 ${known} / 10</span></div><div class="progress" aria-label="问题回答进度"><span style="width:${known*10}%"></span></div>${dimensions.map(([id,name,desc],i)=>`<section class="question"><div class="question-head"><span class="qnum">${String(i+1).padStart(2,'0')}</span><div><h3>${name}</h3><p>${desc}</p></div></div><div class="rating" role="group" aria-label="${name}">${[[0,'不愿意'],[1,'较不愿意'],[2,'一般'],[3,'愿意'],[4,'很愿意'],['unknown','不了解']].map(([v,l])=>choose('interest:'+id,v,l,Object.hasOwn(p.interests,id)&&(v==='unknown'?p.interests[id]===null:p.interests[id]===v),v==='unknown'?'unknown':'')).join('')}</div></section>`).join('')}</div>${stepActions()}`;}
function preferencesStep(){return `${title('03 / 目标与底线','让答案真正影响筛选','优势用于辅助排序；明确不接受的核心学习任务会排除相应样本专业。没选中的项不代表你不擅长。')}<div class="panel">${field('有事实支持的优势 <span class="small">最多选3项，可不选</span>',checks('strengths',strengths),'参考长期表现、作品或经历，不只看一次考试。')}${field('目前最想探索的毕业路径 <span class="small">最多选3项，可不选</span>',checks('goals',goals),'考公、从教或医疗岗位均需另外核对资格与招聘要求。')}${field('明确不接受的核心学习任务 <span class="small">可多选</span>',checks('veto',tasks),'这是排除条件。例如勾选“不接受编程”，会排除以编程为核心学习任务的样本；若只是没接触过，请不要勾选。')}</div><div class="notice">准备好后，你会得到优先探索的专业、推荐原因、冲突提醒，以及选科匹配的院校专业记录。可以保留多个方向再逐项比较。</div>${stepActions()}`;}
function validate(step){if(step===0){if(!subjectSelectionValid(p))return '请选择首选科目，并且恰好选择两门再选科目。';if(p.rank&&(!/^\d+$/.test(p.rank)||+p.rank<1||+p.rank>1000000))return '位次应为1—1000000之间的整数。';if(p.budget&&(!/^\d+$/.test(p.budget)||+p.budget>1000000))return '学费预算应为0—1000000之间的整数。';}if(step>=1&&dimensions.some(([k])=>!Object.hasOwn(p.interests,k)))return '请回答全部10个兴趣问题；没体验过的项目可以选择“不了解”。';return '';}
function results(){return rankMajors(p,db,index);}
function badges(m){return `<span class="tag ${m.eligibility==='matched'?'':m.eligibility==='blocked'?'warn':'gray'}">${m.eligibility==='matched'?`${fmt(m.matching.length)}条同名记录选科匹配`:m.eligibility==='blocked'?'同名记录选科不匹配':'选科记录待核查'}</span>`;}
function card(m,i){return `<article class="major-card"><div class="rank-label">优先探索 ${String(i+1).padStart(2,'0')}</div><h3>${esc(m.name)}</h3><div class="field-name">${esc(m.field)} · 本样本${m.years}年路径</div>${badges(m)}<div class="scoreline"><span class="score">${m.score}</span><span class="small">探索匹配分 / 100</span></div><div class="reasons"><strong>为什么值得先看</strong>${m.positive.length?`你愿意投入${esc(m.positive.slice(0,2).join('、'))}，与该专业部分核心任务相符。`:'目前没有明确的高兴趣线索，先做课程体验。'}</div><p class="muted">课程：${esc(m.courses)}</p>${m.warnings.length?`<div class="warningline">需留意：${esc(m.warnings[0])}</div>`:''}<div class="card-actions"><button class="btn primary sm" data-detail="${m.id}">看具体学习与出口</button><button class="btn sm ${p.compare.includes(m.id)?'selected':''}" data-compare="${m.id}">${p.compare.includes(m.id)?'已加入对比':'加入对比'}</button></div></article>`;}
function resultsPage(){const list=results(),available=list.filter(m=>!m.hard.length),recommended=available.filter(m=>m.hasSignal&&m.coverage>=50&&m.score>=45).slice(0,3),excluded=list.filter(m=>m.hard.length),known=dimensions.filter(([k])=>Number.isFinite(p.interests[k])).length;
return `${title('04 / 筛选结果','先看这几个，再做取舍','排序来自你填写的兴趣、优势和路径偏好。它帮助决定先了解谁，不代替专业体验和招生资格核查。')}<div class="summarybar"><span class="tag">河北2027</span><strong>${esc([p.first,...p.electives].join('＋'))}</strong><span class="small">${p.maxYears==='4'?'本科≤4年':'学制可灵活'} · ${esc(p.grad==='yes'?'愿意深造':p.grad==='no'?'希望本科就业':'深造待定')}</span><button class="textbtn current-profile" data-step="0">修改条件</button></div>
<div class="results-head"><div><h2 style="margin-bottom:6px">${recommended.length?'你的优先探索方向':'先补充体验，再做推荐'}</h2><span class="small">${majors.length}个整理样本中，${available.length}个未触及当前排除条件，${excluded.length}个被排除；不覆盖全部专业。</span></div><div class="choices"><button class="btn sm" data-action="print">打印结果</button><button class="btn sm" data-action="export">导出结果</button></div></div>
${known<6?`<div class="notice warn">你有${10-known}项选择了“不了解”，推荐依据有限。建议先完成课程体验，再回来修改答案。</div>`:''}
${recommended.length?`<div class="top-results">${recommended.map(card).join('')}</div>`:`<div class="empty"><h3>目前没有足够依据给出优先推荐</h3><p>${available.length?'可能是尚无明确兴趣、已知信息太少，或兴趣与底线冲突。先从下方未排除专业做小体验。':'当前选科、学制与底线叠加后，样本全部被排除。查看下方原因，再决定是否调整某一项。'}</p><button class="btn primary" data-step="1">回到兴趣问题</button> <button class="btn" data-step="2">复核我的底线</button></div>`}
<div class="next-action"><div><strong>下一步，把专业变成具体院校候选</strong><p>查看官方表中选科匹配的“专业＋学校”，逐条加入候选清单。</p></div><button class="btn primary" data-action="recommendedSchools" ${recommended.length?'':'disabled'}>看推荐专业的院校 →</button></div>
${p.compare.length?`<div class="notice">已选择${p.compare.length}个专业用于对比。 <button class="textbtn" data-action="compare">打开并排对比</button></div>`:''}
<div class="toolbar"><h3>继续比较未排除的专业</h3><button class="textbtn" data-action="showall">${showAll?'收起更多':'查看全部 '+available.length+' 个'}</button></div><div class="tablewrap"><table class="result-table"><thead><tr><th>专业与方向</th><th>探索匹配</th><th>选科核查</th><th>主要提醒</th><th>操作</th></tr></thead><tbody>${available.slice(0,showAll?available.length:8).map(m=>`<tr><td><strong>${esc(m.name)}</strong><span class="small">${esc(m.field)}</span></td><td>${m.score}分<span class="small">核心兴趣已知${m.coverage}%</span></td><td>${badges(m)}</td><td>${esc(m.warnings[0]||m.note)}</td><td><div class="table-actions"><button class="btn sm" data-detail="${m.id}">详情</button><button class="btn sm ${p.compare.includes(m.id)?'selected':''}" data-compare="${m.id}">${p.compare.includes(m.id)?'取消对比':'对比'}</button></div></td></tr>`).join('')||'<tr><td colspan="5">当前条件下无未排除样本。</td></tr>'}</tbody></table></div>
<details><summary>查看被排除的${excluded.length}个专业及原因</summary><div class="excluded-list">${excluded.map(m=>`<div class="excluded-item"><strong>${esc(m.name)}</strong><p>${m.hard.map(esc).join('；')}</p></div>`).join('')}</div></details><p class="method">分数计算：兴趣70份权重，已填写的优势20份、路径偏好10份；未填写的部分不参与分母；希望本科就业且样本部分岗位常需深造时降低10分优先度。核心兴趣已知不足50%、没有明确兴趣或匹配分低于45，不列为优先推荐。该规则未经职业测评效度验证；分数不是录取概率。<button class="textbtn" data-action="sources">查看数据口径</button></p>`;}
function dataStatus(){return `<div class="notice"><strong>已接入官方2027选科参考表，尚未接入2027实际招生计划。</strong><br>共${fmt(db.records.length)}条拟招记录、${fmt(Object.keys(db.schools).length)}所院校。满足选科不代表在河北该科类一定招生，也不代表符合体检、语种、单科、艺体考试等全部条件。</div>`;}
function filtersHtml(){return `<div class="panel"><div class="filterrow"><label for="schoolSearch">学校名称或院校代码<input class="input" id="schoolSearch" data-filter="school" value="${esc(filters.school)}" placeholder="例如：河北大学"></label><label for="majorSearch">专业名称关键词<input class="input" id="majorSearch" data-filter="major" value="${esc(filters.major)}" placeholder="例如：计算机"></label><label for="levelFilter">层次<select id="levelFilter" data-filter="level"><option ${filters.level==='本科'?'selected':''}>本科</option><option ${filters.level==='高职(专科)'?'selected':''}>高职(专科)</option><option value="" ${filters.level===''?'selected':''}>全部层次</option></select></label><button class="btn primary" data-action="filter">应用筛选</button></div><div style="margin-top:16px" class="choices"><label class="checklabel"><input type="checkbox" id="eligibleOnly" ${filters.onlyEligible?'checked':''}>只看选科匹配</label>${filters.recommended?'<span class="tag">仅看本次优先推荐的同名专业</span><button class="textbtn" data-action="clearRecommended">查看其他专业</button>':''}<span class="small">学校不按排名排序，先按名称展示；无录取位次时不标“冲稳保”。</span></div></div>`;}
function recordId(r){return r.join('|');}
function schoolsPage(){let filtered=filterRecords(db,p,filters);if(filters.recommended){const names=results().filter(m=>!m.hard.length&&m.hasSignal&&m.coverage>=50&&m.score>=45).slice(0,3).map(m=>m.name);filtered=filtered.filter(({r})=>names.includes(r[2]));}
filtered.sort((a,b)=>db.schools[a.r[0]].localeCompare(db.schools[b.r[0]],'zh')||a.r[2].localeCompare(b.r[2],'zh'));
const pages=Math.max(1,Math.ceil(filtered.length/20));page=Math.min(page,pages-1);const selected=[p.first,...p.electives];
return `${title('院校专业库 / 官方选科参考','把方向缩小到具体学校','按你的选科查询官方拟招专业，加入候选后再核实当年计划、校区、学费和录取位次。')}${dataStatus()}${!subjectSelectionValid(p)?'<div class="notice warn">尚未完成选科条件。请先 <button class="textbtn" data-step="0">填写基本条件</button>，再使用“只看选科匹配”。</div>':`<div class="summarybar"><strong>${esc(selected.join('＋'))}</strong><button class="textbtn" data-step="0">修改选科</button><span class="small">仅校验科目要求</span></div>`}${filtersHtml()}<div class="toolbar"><span class="muted small">找到 ${fmt(filtered.length)} 条记录，每页20条</span><button class="btn sm" data-view="saved">查看候选清单（${p.saved.length}）</button></div><div class="tablewrap"><table><thead><tr><th>学校</th><th>专业</th><th>层次 / 原文科目要求</th><th>个人位次对比</th><th>操作</th></tr></thead><tbody>${filtered.slice(page*20,page*20+20).map(({r,i})=>{const eligible=subjectSelectionValid(p)?checkRequirement(db.requirements[r[4]],selected):null,stat=compareRank(history,db.schools[r[0]],r[2],p);return `<tr><td class="school-name"><strong>${esc(db.schools[r[0]])}</strong><span class="small">院校代码 ${esc(r[0])}</span></td><td><strong>${esc(r[2])}</strong><span class="small">专业代码 ${esc(r[1])} · 拟招参考</span></td><td><span class="tag ${eligible===true?'':eligible===false?'warn':'gray'}">${eligible===true?'选科匹配':eligible===false?'选科不匹配':'选科待核'}</span><span class="small">${esc(db.levels[r[3]])} · ${esc(db.requirements[r[4]])}</span></td><td class="history-status">${esc(stat.label)}</td><td><button class="btn sm ${p.saved.includes(i)?'selected':''}" data-save="${i}" ${eligible===false?'disabled':''}>${p.saved.includes(i)?'已加入':'加入候选'}</button></td></tr>`;}).join('')||'<tr><td colspan="5"><div class="empty"><h3>没有匹配记录</h3><p>试试缩短关键词、取消推荐专业限制，或复核选科。无记录不等于全国不存在该方向。</p></div></td></tr>'}</tbody></table></div><div class="pagination"><button class="btn sm" data-action="pageprev" ${page===0?'disabled':''}>上一页</button><span>第${page+1} / ${pages}页</span><button class="btn sm" data-action="pagenext" ${page>=pages-1?'disabled':''}>下一页</button></div>${historyImport()}`;}
function historyImport(){return `<details class="panel import"><summary>已有官方历史录取位次？导入后进行对比</summary><p class="hint">仅接收河北、同科类、同一学校和具体专业的历史最低位次。别混入专项、不同校区或合作项目。学校和专业须与选科表完全同名；仅作历史对比，不预测录取。</p><p class="hint">CSV列名：学校,专业,年份,科类,最低位次,来源。每行注明出处；请从同一口径的官方资料整理。导入数据仅在本次页面会话内使用，不上传服务器。</p><textarea id="historyText" aria-label="粘贴历史位次CSV" placeholder="学校,专业,年份,科类,最低位次,来源"></textarea><div class="choices"><button class="btn" data-action="importHistory">导入粘贴数据</button><label class="btn">选择CSV文件<input id="historyFile" type="file" accept=".csv,text/csv" hidden></label><button class="btn" data-action="historyTemplate">下载空白模板</button></div><p class="hint">本次已导入${fmt(history.length)}行；需连续2024—2026三年，才显示位次区间对比。</p><div id="importError" class="error-message" role="alert"></div></details>`;}
function savedPage(){return `${title('我的候选 / 继续做减法','把愿意读的选项留在这里','候选顺序由你调整。它还不是可直接提交的志愿表，需要对照2027年正式计划逐项确认。')}<div class="summarybar"><strong>${p.saved.length} / 96 个候选</strong><span class="small">96个上限参考河北2026年普通本科批规则，2027年需复核。</span><div class="choices current-profile"><button class="btn sm" data-action="print">打印候选</button><button class="btn sm" data-action="exportSaved">导出CSV</button></div></div>${p.saved.length?`<div class="notice warn">待核事项：实际在河北该科类招生、2027计划数、体检及单科要求、收费与校区、大类分流、专项或定向约束。${p.budget?`你的每年学费预算为${fmt(p.budget)}元；当前表无学费，尚未完成预算核验。`:''}</div><div class="tablewrap"><table><thead><tr><th>顺序</th><th>学校＋专业</th><th>选科与历史位次</th><th>待核事项</th><th>调整</th></tr></thead><tbody>${p.saved.map((i,n)=>{const r=db.records[i],ok=checkRequirement(db.requirements[r[4]],[p.first,...p.electives]),s=compareRank(history,db.schools[r[0]],r[2],p);return `<tr><td>${n+1}</td><td><strong>${esc(db.schools[r[0]])}</strong><span class="small">${esc(r[2])} · ${esc(db.levels[r[3]])}</span><span class="small">${esc(r[0])} / ${esc(r[1])}</span></td><td><span class="tag ${ok?'':'warn'}">${ok?'选科匹配':'选科已不匹配，请移除或复核'}</span><span class="small">${esc(s.label)}</span>${s.rows.map(h=>`<span class="small">${h.year}最低位次：${fmt(h.rank)}（${esc(h.source)}）</span>`).join('')}</td><td class="small">计划、费用、校区、体检等尚未核实</td><td><div class="table-actions saved-order"><button class="btn sm" data-move="${n},-1" aria-label="上移第${n+1}项" ${n===0?'disabled':''}>↑</button><button class="btn sm" data-move="${n},1" aria-label="下移第${n+1}项" ${n===p.saved.length-1?'disabled':''}>↓</button><button class="btn sm" data-remove="${i}">移除</button></div></td></tr>`;}).join('')}</tbody></table></div>`:`<div class="empty"><h3>还没有加入院校专业</h3><p>先完成专业筛选，再从官方选科参考表中选择具体学校与专业。</p><button class="btn primary" data-view="schools">去院校专业库</button></div>`}${historyImport()}`;}
function render(){if(!db)return;if(!['planner','data'].includes(view))delete app.dataset.workspace;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.getElementById('savedCount').textContent=p.saved.length;if(['planner','data'].includes(view)){workspace.render(view);return;}if(view==='assessment')app.innerHTML=`<div class="layout">${sidebar()}<div>${p.step===3?resultsPage():p.step===0?profileStep():p.step===1?interestsStep():preferencesStep()}</div></div>`;else app.innerHTML=view==='schools'?schoolsPage():savedPage();document.querySelectorAll('header [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function setView(next){view=next;render();window.scrollTo({top:0,behavior:'smooth'});}
function setStep(n){if(n===3){const err=validate(0)||validate(1);if(err){toast(err);n=subjectSelectionValid(p)?1:0;}else p.done=true;}p.step=n;view='assessment';persist();render();window.scrollTo({top:0,behavior:'smooth'});}
function openDialog(html){dialogBody.innerHTML=html;if(!dialog.open)dialog.showModal();}
function detail(id){const m=results().find(m=>m.id===id);if(!m)return;openDialog(`<div class="eyebrow">${esc(m.field)}</div><h2 id="dialogTitle">${esc(m.name)}</h2>${badges(m)}<p class="hint">只匹配完全同名专业；专业类、大类试验班或名称变体须另查。不是2027正式招生计划。</p><div class="detailgrid"><div><h3>大学主要学什么</h3><p>${esc(m.courses)}</p></div><div><h3>常见探索出口</h3><p>${esc(m.jobs)}</p></div><div><h3>为什么进入你的视野</h3><p>${m.positive.length?`兴趣线索：${esc(m.positive.join('、'))}`:'没有明确的高兴趣线索，建议先体验。'}<br>探索匹配${m.score}分；核心兴趣信息已知${m.coverage}%。</p></div><div><h3>先核查这一点</h3><p>${esc(m.note)}</p></div></div><div class="notice"><strong>用一次体验做最后筛选</strong><br>${esc(m.trial)}</div>${m.hard.length?`<div class="notice error">${m.hard.map(esc).join('<br>')}</div>`:''}${m.warnings.length?`<div class="notice warn">${m.warnings.map(esc).join('<br>')}</div>`:''}<div class="choices"><button class="btn primary" data-major-schools="${esc(m.name)}">查看同名院校专业</button><button class="btn" data-compare="${m.id}">${p.compare.includes(m.id)?'取消对比':'加入对比'}</button></div>`);}
function compare(){const selected=results().filter(m=>p.compare.includes(m.id));if(selected.length<2){toast('至少选择两个专业，最多四个。');return;}openDialog(`<h2 id="dialogTitle">把专业放在一起比较</h2><div class="tablewrap"><table class="comparetable"><thead><tr><th>比较什么</th>${selected.map(m=>`<th>${esc(m.name)}</th>`).join('')}</tr></thead><tbody>${[['探索匹配',m=>`${m.score}分（非录取概率）`],['主要课程',m=>m.courses],['常见出口',m=>m.jobs],['本科路径',m=>`${m.years}年（具体学校另查）`],['选科匹配记录',m=>`${m.matching.length}条同名记录`],['冲突与提醒',m=>[...m.hard,...m.warnings,m.note].join('；')],['先做一次体验',m=>m.trial]].map(([name,fn])=>`<tr><th>${name}</th>${selected.map(m=>`<td>${esc(fn(m))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="hint">先删掉你不愿意学核心课程、不能接受培养代价的选项；剩余选项再比较具体学校。</p>`);}
function sourceDialog(){openDialog(`<h2 id="dialogTitle">数据与筛选方法</h2><div class="data-stats"><div><strong>${fmt(db.records.length)}</strong><span class="small">官方选科参考记录</span></div><div><strong>${fmt(Object.keys(db.schools).length)}</strong><span class="small">院校</span></div><div><strong>${majors.length}</strong><span class="small">人工整理的专业探索样本</span></div></div><h3>哪些信息是真实数据</h3><p>院校、专业代码、专业名称、层次、选考科目原文来自河北2027年选科要求附件。文件由教育部阳光高考转载发布，下载自其官方附件分发域名。发布日期2025年2月13日，整理日期2026年10月29日。已去除完全重复行，未扩写招生计划。</p><h3>哪些是探索规则</h3><p>专业课程、岗位、体验建议与偏好权重为人工整理。以兴趣70、优势20、路径10的权重辅助排序；未填写的部分不计入分母。希望本科就业且样本部分目标岗位常需深造时，降低10分优先度，但不认定不能本科就业。尚未经过职业测评效度验证，不给出薪资保证、性格定型或录取概率。无明确兴趣或证据不足时，不强行推荐。</p><h3>怎样判断选科</h3><p>逐条按原文匹配全部必选科目。未能识别的要求保留为待核查。专业推荐仅统计完全同名记录；无同名记录不能推出无法报考。满足选科后，仍需核对2027年实际在河北的科类、计划和学校章程。</p><h3>河北规则的适用范围</h3><p>按2026年已公布规则，普通本科批采用“专业（类）＋学校”，最多96个志愿，不设专业服从调剂选项。提前批等其他批次规则不同。2027年具体安排须复核当年政策。</p><h3>隐私与保存</h3><p>不收集姓名、联系方式或身份证。问卷和候选清单保存在当前浏览器；导入历史数据仅在本次页面会话中使用。清除浏览器数据后，本地进度可能丢失，可导出备份。</p><ul class="source-list">${sources.map(([name,url])=>`<li><a href="${url}" target="_blank" rel="noopener noreferrer">${esc(name)}</a></li>`).join('')}</ul>`);}
function download(name,content,type='text/csv;charset=utf-8'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportResults(){const list=results(),rows=[['专业','探索匹配分（非录取概率）','选科组合','选科匹配同名记录数','排除原因','提醒','课程体验建议'],...list.map(m=>[m.name,m.score,[p.first,...p.electives].join('+'),m.matching.length,m.hard.join('；'),m.warnings.join('；'),m.trial])];download('河北专业探索结果.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'));}
function exportSaved(){const rows=[['顺序','院校代码','学校','专业代码','专业','层次','官方选科要求','个人科目组合','历史位次对比','待核事项'],...p.saved.map((i,n)=>{const r=db.records[i];return [n+1,r[0],db.schools[r[0]],r[1],r[2],db.levels[r[3]],db.requirements[r[4]],[p.first,...p.electives].join('+'),compareRank(history,db.schools[r[0]],r[2],p).label,'2027实际计划、体检、单科、费用、校区、项目资格待核'];})];download('河北院校专业候选清单.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'));}
function printReport(){const recommended=results().filter(m=>!m.hard.length&&m.hasSignal&&m.coverage>=50&&m.score>=45).slice(0,3);document.getElementById('printReport').innerHTML=`<h1>河北2027专业探索与院校候选</h1><p>科目组合：${esc([p.first,...p.electives].join('＋'))}；${p.rank?`个人位次：${fmt(p.rank)}`:'个人位次未填'}；${p.budget?`年学费预算：${fmt(p.budget)}元（尚未核实）`:'学费预算未填'}。</p><p class="small">依据2027年选科参考表，不等于当年实际招生计划。探索匹配分不是录取概率。</p><h2>优先探索的专业</h2>${recommended.map(m=>`<div class="print-block"><h3>${esc(m.name)} · 探索匹配${m.score}分</h3><p>兴趣线索：${esc(m.positive.join('、'))}。选科匹配同名记录${m.matching.length}条。</p><p>课程：${esc(m.courses)}。出口：${esc(m.jobs)}。</p><p>体验：${esc(m.trial)}</p><p>核查：${esc([...m.warnings,m.note].join('；'))}</p></div>`).join('')||'<p>当前证据不足，未给出优先推荐。</p>'}<h2>院校专业候选（按当前顺序）</h2><table><thead><tr><th>顺序</th><th>学校＋专业</th><th>科目要求</th><th>位次对比</th></tr></thead><tbody>${p.saved.map((i,n)=>{const r=db.records[i];return `<tr><td>${n+1}</td><td>${esc(db.schools[r[0]])}<br>${esc(r[2])}<br>${r[0]} / ${r[1]}</td><td>${esc(db.requirements[r[4]])}</td><td>${esc(compareRank(history,db.schools[r[0]],r[2],p).label)}</td></tr>`;}).join('')||'<tr><td colspan="4">尚未加入院校专业。</td></tr>'}</tbody></table><h2>提交前核查</h2><p>□实际招生计划与科类　□体检、语种及单科　□费用与校区　□大类分流　□专项及定向约束　□按本省规则及真实意愿排序</p><p class="small">来源：河北2027年选科要求发布页：${sources[0][1]}。河北普通本科批模式参考2026年规则，2027年需复核。</p>`;window.print();}
function importHistory(text){try{history=validateHistory(text);render();toast(`已导入${history.length}行历史位次数据。`);}catch(e){const target=document.getElementById('importError');if(target)target.textContent=e.message;else toast(e.message);}}
const workspace=createWorkspace({root:app,getProfile:()=>p,getRequirements:()=>db,getRecommendations:()=>results().filter(m=>!m.hard.length&&m.coverage>=50&&m.hasSignal&&m.score>=45),toast});
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||b.disabled||!db)return;
 if(b.dataset.choice){const k=b.dataset.choice,v=b.dataset.value;if(k.startsWith('interest:'))p.interests[k.split(':')[1]]=v==='unknown'?null:+v;else if(['electives','strengths','goals','veto'].includes(k)){const arr=p[k];if(arr.includes(v))p[k]=arr.filter(x=>x!==v);else if(arr.length<(k==='electives'?2:k==='veto'?20:3))arr.push(v);else return toast(k==='electives'?'再选科目只能选择两门，请先取消一项。':'最多选择三项，请先取消一项。');}else p[k]=v;persist();const scroll=window.scrollY;render();window.scrollTo(0,scroll);return;}
 if(b.dataset.step!==undefined){if(dialog.open)dialog.close();setStep(+b.dataset.step);return;}
 if(b.dataset.view){if(dialog.open)dialog.close();setView(b.dataset.view);return;}
 if(b.dataset.detail){detail(b.dataset.detail);return;}
 if(b.dataset.compare){const id=b.dataset.compare;if(p.compare.includes(id))p.compare=p.compare.filter(x=>x!==id);else if(p.compare.length<4)p.compare.push(id);else return toast('最多同时对比4个专业。');persist();const open=dialog.open;render();if(open)detail(id);toast(`已选${p.compare.length}个专业，可在结果页打开并排对比。`);return;}
 if(b.dataset.majorSchools){dialog.close();filters.major=b.dataset.majorSchools;filters.recommended=false;filters.onlyEligible=true;filters.level='本科';page=0;setView('schools');return;}
 if(b.dataset.save!==undefined){const i=+b.dataset.save;if(p.saved.includes(i))p.saved=p.saved.filter(x=>x!==i);else {if(p.saved.length>=96)return toast('当前候选最多96项，请先移除不愿就读的选项。');p.saved.push(i);}persist();render();return;}
 if(b.dataset.remove!==undefined){p.saved=p.saved.filter(i=>i!==+b.dataset.remove);persist();render();return;}
 if(b.dataset.move){const [i,d]=b.dataset.move.split(',').map(Number),j=i+d;if(j>=0&&j<p.saved.length)[p.saved[i],p.saved[j]]=[p.saved[j],p.saved[i]];persist();render();return;}
 switch(b.dataset.action){
  case 'next':{const err=validate(p.step);if(err){document.getElementById('validation').textContent=err;return;}setStep(p.step+1);break;}
  case 'prev':setStep(p.step-1);break;
  case 'showall':showAll=!showAll;render();break;
  case 'compare':compare();break;
  case 'sources':sourceDialog();break;
  case 'recommendedSchools':filters={...filters,major:'',recommended:true,onlyEligible:true,level:'本科'};page=0;setView('schools');break;
  case 'clearRecommended':filters.recommended=false;page=0;render();break;
  case 'filter':filters.school=document.getElementById('schoolSearch').value;filters.major=document.getElementById('majorSearch').value;filters.level=document.getElementById('levelFilter').value;filters.onlyEligible=document.getElementById('eligibleOnly').checked;page=0;render();break;
  case 'pageprev':page=Math.max(0,page-1);render();break;
  case 'pagenext':page++;render();break;
  case 'export':exportResults();break;
  case 'exportSaved':exportSaved();break;
  case 'print':printReport();break;
  case 'importHistory':importHistory(document.getElementById('historyText').value);break;
  case 'historyTemplate':download('河北历史位次导入模板.csv','\uFEFF学校,专业,年份,科类,最低位次,来源\r\n');break;
 }
});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.field){p[t.dataset.field]=t.value;persist();}if(t.id==='historyFile'&&t.files?.[0]){if(t.files[0].size>15*1024*1024)return toast('文件过大，请控制在15MB以内。');importHistory(await t.files[0].text());}if(t.id==='eligibleOnly'){filters.onlyEligible=t.checked;page=0;render();}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.dataset.filter)document.querySelector('[data-action="filter"]')?.click();});
document.getElementById('sourcesBtn').addEventListener('click',()=>db&&sourceDialog());document.getElementById('closeDialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.getElementById('clearBtn').addEventListener('click',()=>openDialog('<h2 id="dialogTitle">清除本机记录？</h2><p>将清除专业问卷、专业对比、旧候选清单和本次会话导入数据。96方案工作台的计划与版本另行保留，可从数据工作台导出备份。可以先关闭此弹窗并导出结果。</p><button class="btn" id="confirmClear">确认清除</button>'));
dialog.addEventListener('click',e=>{if(e.target.id==='confirmClear'){p=defaults();history=[];persist();dialog.close();setView('assessment');toast('已清除本机记录。');}});
async function init(){try{const r=await fetch('./requirements.json');if(!r.ok)throw Error('HTTP '+r.status);db=await r.json();index=buildIndex(db);p.saved=p.saved.filter(i=>db.records[i]);p.compare=p.compare.filter(i=>majors.some(m=>m.id===i));if(p.step===3&&(validate(0)||validate(1)))p.step=0;render();}catch(e){app.innerHTML='<div class="empty"><h1>选科数据未能加载</h1><p>请检查网络后重试。数据未加载时不会显示虚构的推荐或选科结论。</p><button class="btn primary" id="retryLoad">重新加载</button></div>';document.getElementById('retryLoad').onclick=init;}}
init();
